const items = $input.all();
let folder_id = '';
try {
  const first = items[0] && items[0].json;
  if (Array.isArray(first) && first.length > 0) folder_id = first[0].value || '';
  else if (first && typeof first === 'object') folder_id = first.value || '';
} catch (e) {}
const ok = folder_id && !/YOUR_|PLACEHOLDER|HERE/i.test(folder_id) && folder_id.length >= 12;
return [{ json: { folder_id: ok ? folder_id : '' } }];

const items = $input.all();
const first = (items[0] && items[0].json) || {};
const READABLE = new Set(['application/vnd.google-apps.document','text/plain','text/markdown','application/vnd.google-apps.spreadsheet']);
const files = (first.files || []).filter(f => READABLE.has(f.mimeType));
if (files.length === 0) return [{ json: { _empty: true } }];
return files.map(f => ({ json: { id: f.id, name: f.name, mimeType: f.mimeType, modifiedTime: f.modifiedTime } }));

const items = $input.all();
const list = $('Drive Filter Readable').all().map(i => i.json);
const docs = [];
for (let i = 0; i < items.length; i++) {
  const meta = list[i] || {};
  const body = String((items[i] && items[i].json && (items[i].json.data || items[i].json.body || JSON.stringify(items[i].json))) || '').slice(0, 8000);
  if (!body || body.length < 80) continue;
  docs.push({ id: meta.id, name: meta.name, mime_type: meta.mimeType, modified: meta.modifiedTime, body, url: meta.mimeType === 'application/vnd.google-apps.document' ? 'https://docs.google.com/document/d/' + meta.id + '/edit' : meta.mimeType === 'application/vnd.google-apps.spreadsheet' ? 'https://docs.google.com/spreadsheets/d/' + meta.id + '/edit' : 'https://drive.google.com/file/d/' + meta.id + '/view' });
}
return [{ json: { drive_docs: docs, drive_count: docs.length } }];

const ideasRaw = $('Load Recent Ideas').all().map(i => i.json);
const ideas = Array.isArray(ideasRaw[0]) ? ideasRaw[0] : ideasRaw;
const signalsRaw = $('Load Recent Signals').all().map(i => i.json);
const signals = Array.isArray(signalsRaw[0]) ? signalsRaw[0] : (signalsRaw && signalsRaw[0] && !signalsRaw[0].error ? signalsRaw : []);
let drive_docs = [];
try { const a = $('Drive Aggregate').first(); if (a && a.json && Array.isArray(a.json.drive_docs)) drive_docs = a.json.drive_docs; } catch (e) {}
if (drive_docs.length === 0) { try { const s = $('Drive Skip Empty').first(); if (s && s.json && Array.isArray(s.json.drive_docs)) drive_docs = s.json.drive_docs; } catch (e) {} }
const pillarsRaw = $('Load Pillars').all().map(i => i.json);
const pillars = Array.isArray(pillarsRaw[0]) ? pillarsRaw[0] : pillarsRaw;
const briefRaw = $('Load Cleo Brief').all().map(i => i.json);
const briefArr = Array.isArray(briefRaw[0]) ? briefRaw[0] : briefRaw;
const brief = (briefArr[0] && briefArr[0].brief_content) || '';
const cfgRaw = $('Load Synthesis Thresholds').all().map(i => i.json);
const cfgArr = Array.isArray(cfgRaw[0]) ? cfgRaw[0] : cfgRaw;
const cfg = {};
for (const row of cfgArr) cfg[row.key] = row.value;
const minConf = parseFloat(cfg.cleo_synthesis_min_confidence || '0.85');
const minThreads = parseInt(cfg.cleo_synthesis_min_threads || '3', 10);
const minEntities = parseInt(cfg.cleo_synthesis_min_named_entities || '3', 10);

const pillarsBlock = pillars.map(p => {
  const gl = p.good_looks_like || {};
  const ap = (p.anti_patterns || []).map(x => '  - ' + x).join('\n');
  const er = (p.evidence_required || []).map(x => '  - ' + x).join('\n');
  return '### ' + p.name + ' (id: ' + p.id + ')\n' +
         '**Description:** ' + p.description + '\n' +
         '**Voice:** ' + (gl.voice || '') + '\n' +
         '**Anti-patterns:**\n' + ap + '\n' +
         '**Evidence required:**\n' + er;
}).join('\n\n');

const ideasBlock = ideas.length === 0
  ? '(no recent ideas)'
  : ideas.map(i => '- [' + i.id + '] (' + (i.pillar_id || 'no-pillar') + ', ' + (i.state || 'unknown') + ') ' + i.idea + (i.thesis ? '\n    THESIS: ' + i.thesis : '') + (i.source_url ? '\n    SOURCE: ' + i.source_url : '')).join('\n');

const signalsBlock = signals.length === 0
  ? '(no recent signals)'
  : signals.map(s => '- [' + s.id + '] ' + (s.title || '') + ' (' + (s.source || 'unknown') + ')' + (s.summary ? '\n    ' + s.summary : '') + (s.source_url ? '\n    URL: ' + s.source_url : '')).join('\n');

const driveBlock = drive_docs.length === 0
  ? '(no inspiration docs)'
  : drive_docs.map(d => '--- DOC: ' + d.name + ' ---\nURL: ' + (d.url || '') + '\nBODY:\n' + d.body).join('\n\n');

const systemPrompt =
  (brief ? 'AGENT BRIEF:\n' + brief + '\n\n---\n\n' : '') +
  'Weekly cross-thread synthesis for Krish. Hypothesize 0 to 3 non-obvious angles connecting 3+ of the threads below into a single sharp take that NO source states directly.\n\n' +
  '## THE BAR (highest in the system)\n\n' +
  '1. CONNECTS ' + minThreads + '+ THREADS. Identify content_ideas IDs, zara_signals IDs, drive doc names that feed each hypothesis.\n' +
  '2. NON-OBVIOUS. The angle must not be stated directly by any source. If you can quote one source making the same claim, drop it.\n' +
  '3. FALSIFIABLE. The hypothesis must make a claim provably wrong by a specific observation in the next 90 days. "AI is important" is not falsifiable.\n' +
  '4. PILLAR-LINKED. Maps to exactly one pillar.\n' +
  '5. CONFIDENCE >= ' + minConf + '. If you would not bet reputation on it, do not include it.\n' +
  '6. EVIDENCE-DENSE. At least ' + minEntities + ' named entities (publisher, deal, tool, number, date) cited across the source threads.\n\n' +
  'If no hypothesis meets all six, return []. Zero is a valid output.\n\n' +
  '## KRISH PILLARS\n\n' + pillarsBlock + '\n\n' +
  '## KRISH VOICE RULES\n' +
  '- Declarative and specific. No hedging.\n' +
  '- NO em dashes. Use commas, colons, parentheses, line breaks.\n' +
  '- Banned phrases: leveraging, unlocking, delve into, fast-paced world, navigating, robust, synergies.\n\n' +
  '## OUTPUT\n' +
  'Strict JSON array. No preamble, no markdown fence.\n' +
  '[\n' +
  '  {\n' +
  '    "hypothesis": "one-sentence angle in Krish voice",\n' +
  '    "thesis": "2-3 sentences. The claim, the why, the falsifiable test.",\n' +
  '    "pillar_id": "pillar:open_web_econ",\n' +
  '    "connected_threads": [\n' +
  '      {"type": "content_idea", "id": "uuid", "title": "..."},\n' +
  '      {"type": "zara_signal", "id": "uuid", "title": "..."},\n' +
  '      {"type": "inspiration_doc", "name": "filename"}\n' +
  '    ],\n' +
  '    "falsifiable_test": "what observation in the next 90 days would prove this wrong",\n' +
  '    "confidence": 0.9,\n' +
  '    "named_entities": ["publisher: Vox", "deal: Publicis-LiveRamp", "figure: $2.2B"],\n' +
  '    "why_non_obvious": "1-2 sentences explaining why no single source states this",\n' +
  '    "distribution": ["linkedin", "newsletter"]\n' +
  '  }\n' +
  ']';

const userPrompt =
  '=== RECENT CONTENT IDEAS (last 14 days, ' + ideas.length + ' items) ===\n' + ideasBlock + '\n\n' +
  '=== RECENT ZARA SIGNALS (last 14 days, ' + signals.length + ' items) ===\n' + signalsBlock + '\n\n' +
  '=== INSPIRATION FOLDER (last 14 days, ' + drive_docs.length + ' docs) ===\n' + driveBlock + '\n\n' +
  'Synthesize now. Strict JSON array only.';

const anthropic_body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 4000,
  system: systemPrompt,
  messages: [{ role: 'user', content: userPrompt }],
};
return [{ json: { anthropic_body, ideas_count: ideas.length, signals_count: signals.length, docs_count: drive_docs.length, min_confidence: minConf, min_threads: minThreads, min_entities: minEntities, pillar_ids: pillars.map(p => p.id) } }];

const items = $input.all();
const src = (items[0] && items[0].json) || {};
const body = src.anthropic_body || {};
const msgs = body.messages || [];
let promptText = (body.system || '') + '\n\n';
for (const m of msgs) {
  const c = typeof m.content === 'string' ? m.content : JSON.stringify(m.content);
  promptText += (m.role === 'user' ? c : '[assistant]: ' + c) + '\n\n';
}
const gemini_body = {
  contents: [{ parts: [{ text: promptText.trim() }] }],
  generationConfig: { maxOutputTokens: body.max_tokens || 4000, temperature: body.temperature || 0.4 },
};
return [{ json: { gemini_body } }];

const items = $input.all();
const d = (items[0] && items[0].json) || {};
let raw = '';
let model_used = 'claude-sonnet-4-6';
if (d.content && d.content[0] && d.content[0].text) { raw = d.content[0].text; }
else if (d.candidates && d.candidates[0]) { raw = ((d.candidates[0].content || {}).parts || [{}])[0].text || ''; model_used = 'gemini-2.5-pro-fallback'; }
const usage = d.usage || {};
const inputTokens = usage.input_tokens || 0;
const outputTokens = usage.output_tokens || 0;
const cost_usd = (inputTokens / 1000000) * 15.0 + (outputTokens / 1000000) * 75.0;
const ctx = $('Build Synthesis Prompt').first().json;
const minConf = parseFloat(ctx.min_confidence || 0.85);
const minThreads = parseInt(ctx.min_threads || 3, 10);
const minEntities = parseInt(ctx.min_entities || 3, 10);
const validPillars = new Set(ctx.pillar_ids || []);
let arr = [];
try {
  const m = raw.match(/\[[\s\S]*\]/);
  if (m) arr = JSON.parse(m[0]);
} catch (e) { arr = []; }
if (!Array.isArray(arr)) arr = [];
const rejected_reasons = {};
function bump(k) { rejected_reasons[k] = (rejected_reasons[k] || 0) + 1; }
const VAGUE = [/time will tell/i, /^we will see/i, /^future will/i, /^eventually /i];
const survivors = [];
for (const h of arr) {
  if (!h || typeof h !== 'object') { bump('not_object'); continue; }
  if (!h.hypothesis || String(h.hypothesis).trim().length < 12) { bump('hypothesis_too_short'); continue; }
  if (!Array.isArray(h.connected_threads) || h.connected_threads.length < minThreads) { bump('below_min_threads'); continue; }
  if (typeof h.confidence !== 'number' || h.confidence < minConf) { bump('below_min_confidence'); continue; }
  if (!Array.isArray(h.named_entities) || h.named_entities.length < minEntities) { bump('below_min_entities'); continue; }
  if (!h.falsifiable_test || String(h.falsifiable_test).trim().length < 12 || VAGUE.some(rx => rx.test(h.falsifiable_test))) { bump('vague_falsifiable_test'); continue; }
  if (!h.pillar_id || !validPillars.has(h.pillar_id)) { bump('invalid_pillar'); continue; }
  survivors.push(h);
}
return [{ json: { survivors, survivors_count: survivors.length, rejected_count: arr.length - survivors.length, rejected_reasons, raw_count: arr.length, model_used, cost_usd: Math.round(cost_usd * 100000) / 100000 } }];

const d = ($input.first() && $input.first().json) || {};
const survivors = d.survivors || [];
return survivors.map(s => ({ json: s }));
